/**
 * esbuild 构建配置（替代 scripts/build.mjs 的 CJS 拼接打包器）。
 *
 * 策略（B1 分批迁移期）：
 *   - 入口 src/main.js / src/main.ts 自动探测（迁移完批 4 后只留 .ts）
 *   - bundle 成单文件 main.js，external: obsidian / electron / sharp 等
 *   - loader 按扩展名：.ts 与 .js 混合源码都能进同一个产物
 *   - 产物带 sourcemap 注释行（便于运行时栈定位，不生成独立 map 文件）
 *
 * 用法：
 *   node scripts/esbuild.config.mjs          # 构建
 *   node scripts/esbuild.config.mjs --check  # 构建 + tsc --noEmit 类型检查
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(__dirname, "..");
const esbuild = require(path.join(rootDir, "node_modules", "esbuild"));

const entryTs = path.join(rootDir, "src", "main.ts");
const entryJs = path.join(rootDir, "src", "main.js");
const entry = fs.existsSync(entryTs) ? entryTs : entryJs;
const outdir = rootDir;

const EXTERNAL = [
  "obsidian",
  "electron",
  "@open-file-viewer/core",
  "sharp",
  "child_process",
  "fs",
  "path",
  "crypto",
  "util",
  "module"
];

async function main() {
  const result = await esbuild.build({
    entryPoints: [entry],
    bundle: true,
    format: "cjs",
    platform: "node",
    target: "node18",
    outfile: path.join(outdir, "main.js"),
    external: EXTERNAL,
    loader: { ".ts": "ts", ".js": "js" },
    resolveExtensions: [".ts", ".js"],
    sourcemap: false,
    logLevel: "info",
    metafile: true,
    banner: {
      js: "/* THIS IS A GENERATED/BUNDLED FILE BY scripts/esbuild.config.mjs - DO NOT EDIT DIRECTLY */"
    }
  });

  const bytes = fs.statSync(path.join(outdir, "main.js")).size;
  const modules = Object.keys(result.metafile.inputs).length;
  console.log(`Built main.js (${modules} modules, ${(bytes / 1024).toFixed(0)} KB) from ${path.basename(entry)}`);

  if (process.argv.includes("--check")) {
    const { execFileSync } = require("node:child_process");
    try {
      execFileSync(path.join(rootDir, "node_modules", ".bin", "tsc"), ["--noEmit", "-p", rootDir], {
        stdio: "inherit",
        cwd: rootDir
      });
      console.log("tsc --noEmit: PASS");
    } catch (e) {
      process.exitCode = 1;
      console.error("tsc --noEmit: FAILED");
    }
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
